cat << 'EOF' > /app/my-site/src/main.tsx
import React from 'react'
import ReactDOM from 'react-dom/client'
import './style.css'
import { App } from './App'

const path = window.location.pathname;
let page = 'home';
if (path.includes('learn.html')) page = 'learn';
else if (path.includes('donate.html')) page = 'donate';
else if (path.includes('tag-ai.html')) page = 'tag-ai';
else if (path.includes('tag-web-scraping.html')) page = 'tag-web-scraping';

ReactDOM.createRoot(document.getElementById('app')!).render(
  <React.StrictMode>
    <App page={page} />
  </React.StrictMode>,
)
EOF

